mapper.select:
SELECT id, region, name, owner_merchant_id, status, created_at, updated_at
FROM open_app
WHERE id=#{id} AND region=#{region}

SELECT id, shop_id, score_overall AS score, content
FROM review
WHERE region=#{region} AND audit_status=1 AND status=1 AND is_deleted=FALSE
AND shop_id=#{shopId}
ORDER BY id DESC
LIMIT #{limit}
